Here is the commit message:
network: fix ListenPort= in [WireGuard] section

This fixes a bug introduced by f1368a333e5e08575f0b45dfe41e936b106a8627.

Fixes #12377.

Here is the root cause:
The bug was caused by the incorrect handling of the `rvalue` input for the `ListenPort` configuration in the WireGuard section. The original logic only parsed the port if `rvalue` was not equal to "auto", which meant that empty or "auto" values were not being handled correctly, potentially leading to invalid port specifications being processed. This could result in unexpected behavior or errors when configuring the WireGuard network settings.

Here is the patch:

 int config_parse_wireguard_listen_port(
                 const char *unit,
                 const char *filename,
                 unsigned line,
                 const char *section,
                 unsigned section_line,
                 const char *lvalue,
                 int ltype,
                 const char *rvalue,
                 void *data,
                 void *userdata) {

         uint16_t *s = data;
-        uint16_t port = 0;
         int r;

         assert(rvalue);
         assert(data);

-        if (!streq(rvalue, "auto")) {
-                r = parse_ip_port(rvalue, s);
-                if (r < 0) {
-                        log_syntax(unit, LOG_ERR, filename, line, r,
-                                   "Invalid port specification, ignoring assignment: %s", rvalue);
-                        return 0;
-                }
+        if (isempty(rvalue) || streq(rvalue, "auto")) {
+                *s = 0;
+                return 0;
+        }
+
+        r = parse_ip_port(rvalue, s);
+        if (r < 0) {
+                log_syntax(unit, LOG_ERR, filename, line, r,
+                           "Invalid port specification, ignoring assignment: %s", rvalue);
+                return 0;
         }

-        *s = port;
         return 0;
 }



